"use client"

import React from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { useDataStore } from "@/lib/data-store"
import { useI18n } from "@/lib/i18n"
import { useToast } from "@/hooks/use-toast"

export function LegacyProjectPayroll() {
  const { projects, projectAccounting } = useDataStore()
  const payWorkerOnProject = useDataStore((s) => (s as any).payWorkerOnProject)
  const { toast } = useToast()
  const { t } = useI18n()

  // Find completed projects
  const completedProjects = projects.filter((p: any) => (p.status || '').toString().toUpperCase() === 'COMPLETED')

  const handleMarkPaid = async (projectId: string, workerId: string) => {
    const projectKey = projectId
    const success = await payWorkerOnProject(projectKey, workerId)
    if (success) {
      toast({ title: t("toast.successTitle"), description: t("admin.payroll.workerMarked") })
    } else {
      toast({ title: t("toast.errorTitle"), description: t("admin.payroll.markFailed"), variant: 'destructive' })
    }
  }

  return (
        <div className="space-y-6">
          <p className="text-sm text-muted-foreground">{t("admin.payroll.description")}</p>

          {completedProjects.length === 0 && (
            <Card>
              <CardHeader>
                <CardTitle>{t("admin.payroll.noCompleted")}</CardTitle>
              </CardHeader>
              <CardContent>{t("admin.payroll.willAppear")}</CardContent>
            </Card>
          )}

          {completedProjects.map((proj: any) => {
            const acct = projectAccounting.find((a) => a.projectId === (proj.projectKey || proj.id))
            const pending = (acct?.workers || []).filter((w: any) => w.status === 'PENDING_PAYMENT')
            return (
              <Card key={proj.id}>
                <CardHeader>
                  <CardTitle>{proj.name}</CardTitle>
                </CardHeader>
                <CardContent>
                  {pending.length === 0 ? (
                    <div className="text-sm text-muted-foreground">{t("admin.payroll.noPendingWorkers")}</div>
                  ) : (
                    <div className="grid gap-2">
                      <div className="overflow-x-auto">
                        <table className="w-full table-auto">
                          <thead>
                            <tr className="text-left text-sm text-muted-foreground">
                              <th>{t("admin.payroll.worker")}</th>
                              <th>{t("admin.payroll.days")}</th>
                              <th>{t("admin.payroll.rate")}</th>
                              <th>{t("admin.payroll.total")}</th>
                              <th>{t("admin.payroll.actions")}</th>
                            </tr>
                          </thead>
                          <tbody>
                            {pending.map((w: any) => (
                              <tr key={w.id} className="border-t">
                                <td className="py-2">{w.name}</td>
                                <td>{(w.days || []).length}</td>
                                <td>{(w.salaryRate || 0).toFixed(2)} USD</td>
                                <td>{(w.totalPayment || 0).toFixed(2)} USD</td>
                                <td>
                                                    <Button size="sm" onClick={() => handleMarkPaid(proj.projectKey || proj.id, w.id)}>
                                    {t("admin.payroll.markPaid")}
                                  </Button>
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            )
          })}
        </div>
  )
}
